s=replace_once(s,"    this.environment=new Environment(this.scene,seed,saved ? saved.worldGeneration ?? 1 : 2);","    await this.loadingStage(20,'Shaping terrain');\n    this.environment=new Environment(this.scene,seed,saved ? saved.worldGeneration ?? 1 : 2);",'terrain stage')
s=replace_once(s,"    this.environment.syncNodes(this.simulation.state.nodeChanges);","    this.environment.syncNodes(this.simulation.state.nodeChanges);\n    await this.loadingStage(42,'Placing resources');",'resource stage')
s=replace_once(s,"    this.physics=new PhysicsWorld(this.environment.terrainGeometry,this.environment.colliders,this.simulation.state.player.position);","    this.physics=new PhysicsWorld(this.environment.terrainGeometry,this.environment.colliders,this.simulation.state.player.position);\n    await this.loadingStage(56,'Building collision world');",'physics stage')
s=replace_once(s,"    this.worldSurvival=new WorldSurvival(this.environment,this.scene,seed);this.worldSurvival.populate(this.simulation.state);this.physics.setStructure('landmarks',this.worldSurvival.collisionBoxes());this.weather=new Weather(this.scene);","    this.worldSurvival=new WorldSurvival(this.environment,this.scene,seed);this.worldSurvival.populate(this.simulation.state);this.physics.setStructure('landmarks',this.worldSurvival.collisionBoxes());this.weather=new Weather(this.scene);\n    await this.loadingStage(70,'Growing the island');",'survival stage')
s=replace_once(s,"    this.registerNodes();this.createWaterSource();this.syncStructures();this.syncWorldItems();this.syncHeld();this.applySettings(this.settings);this.player.tick(1/60,this.simulation.state,false);this.accumulator=0;this.autoSave=0;this.building=false;this.candidate=null;","    this.registerNodes();this.createWaterSource();this.syncStructures();this.syncWorldItems();this.syncHeld();this.applySettings(this.settings);this.player.tick(1/60,this.simulation.state,false);this.accumulator=0;this.autoSave=0;this.building=false;this.candidate=null;\n    await this.loadingStage(86,'Finalizing world systems');",'final world stage')
s=replace_once(s,"try {await new Promise<void>(resolve=>requestAnimationFrame(()=>resolve()));await this.makeWorld(Number.isFinite(seed)?Math.trunc(seed):WORLD.SEED,saved);this.activeWorld=true;this.screen='playing';this.ui.setScreen('playing');this.ui.notify(saved?'Welcome back to your island.':'Washed ashore. Everything begins here.');}","try {await new Promise<void>(resolve=>requestAnimationFrame(()=>resolve()));await this.makeWorld(Number.isFinite(seed)?Math.trunc(seed):WORLD.SEED,saved);await this.warmUpWorld();this.activeWorld=true;this.screen='playing';this.ui.setScreen('playing');this.ui.notify(saved?'Welcome back to your island.':'Washed ashore. Everything begins here.');}",'start warmup')
anchor="  private setScreen(screen:Screen){"
methods="""  private async loadingStage(progress:number,status:string){this.ui.setLoadingProgress(progress,status);await new Promise<void>(resolve=>requestAnimationFrame(()=>resolve()));}\n  private async warmUpWorld(){\n    await this.loadingStage(90,'Compiling shaders');\n    try{this.renderer.compile(this.scene,this.camera);}catch{ /* A normal render below still warms the pipeline. */ }\n    for(let i=0;i<6;i++){this.renderer.render(this.scene,this.camera);this.ui.setLoadingProgress(92+(i+1)*1.25,'Warming renderer');await new Promise<void>(resolve=>requestAnimationFrame(()=>resolve()));}\n    this.frameMs=16.7;this.fps=60;this.last=performance.now();\n    this.ui.setLoadingProgress(100,'Ready');\n    await new Promise<void>(resolve=>setTimeout(resolve,80));\n  }\n"""
if anchor not in s: raise SystemExit('setScreen anchor missing')
