# 5) Version and changelog.
p='src/config/version.ts';s=read(p)
s=s.replace("GAME_VERSION='0.2.1'","GAME_VERSION='0.2.2'",1).replace("GAME_BUILD='EA-02.1'","GAME_BUILD='EA-02.2'",1)
needle="export const CHANGELOG:ChangeEntry[]=[\n"
entry="""export const CHANGELOG:ChangeEntry[]=[\n  {version:'0.2.2',date:'2026-09-11',title:'Input stability & loading warm-up',changes:[\n    'Added real staged loading progress and renderer warm-up before the world is revealed.',\n    'Mouse look is now coalesced once per render frame instead of applying every browser event immediately.',\n    'Large pointer-lock bursts are capped so a short browser or GPU stall cannot throw the camera sideways.',\n    'Mouse deltas are normalized for high-DPI displays to make Windows and Retina behaviour more consistent.',\n    'Expanded sensitivity down to 0.05x and reduced the base look scale for precise low-sensitivity play.',\n    'Reset FPS timing after warm-up so startup compilation frames do not pollute the live FPS meter.'\n  ]},\n"""
s=replace_once(s,needle,entry,'version changelog entry')
write(p,s)

for file in ['package.json','package-lock.json']:
    p=file;s=read(p);s=s.replace('"version": "0.2.1"','"version": "0.2.2"',2);write(p,s)

p='CHANGELOG.md';s=read(p)
block="""## 0.2.2 — 2026-09-11\n\nInput stability and loading warm-up patch.\n\n- Added a real staged world-loading meter with named phases and percentages.\n- Pre-compiles shaders and renders warm-up frames before gameplay/menu is revealed.\n- Mouse-look events are coalesced once per display frame instead of changing the camera for every browser event.\n- Caps accumulated mouse bursts after stalls to prevent sudden camera jumps.\n- Normalizes pointer movement for high-DPI/Retina displays.\n- Sensitivity now ranges from `0.05×` to `2.50×` with a lower base rotation scale.\n- Resets FPS timing after warm-up so shader compilation no longer appears as sustained low startup FPS.\n\n"""
s=replace_once(s,'# Tideland changelog\n\n','# Tideland changelog\n\n'+block,'markdown changelog')
write(p,s)

# 6) Pure unit coverage for the input filter.
write('tests/mouse-look-filter.test.ts', '''import {describe,expect,it} from 'vitest';\nimport {MouseLookFilter} from '../src/input/MouseLookFilter';\n\ndescribe('MouseLookFilter',()=>{\n  it('normalizes high-DPI pointer deltas',()=>{const f=new MouseLookFilter();f.add(20,-10,2);expect(f.consume()).toEqual({x:10,y:-5});});\n  it('coalesces multiple events and clears after consume',()=>{const f=new MouseLookFilter();f.add(4,3);f.add(6,2);expect(f.consume()).toEqual({x:10,y:5});expect(f.consume()).toEqual({x:0,y:0});});\n  it('caps a stalled event burst while preserving direction',()=>{const f=new MouseLookFilter(180);f.add(3000,4000);const d=f.consume();expect(Math.hypot(d.x,d.y)).toBeCloseTo(180,6);expect(d.x/d.y).toBeCloseTo(3/4,6);});\n  it('ignores non-finite browser deltas',()=>{const f=new MouseLookFilter();f.add(Number.NaN,4);expect(f.consume()).toEqual({x:0,y:0});});\n});\n''')
print('v0.2.2 patch applied')
